def effect_path(slug):
    # Copy assets into user data so saved projects survive app updates / one-file temp extraction.
    root=Path(getattr(sys,'_MEIPASS',Path(__file__).resolve().parent))
    source=root/'effects_assets'/(slug+'.png')
    target=Path.home()/'.fragforge'/'effects'/(slug+'.png')
    target.parent.mkdir(parents=True,exist_ok=True)
    if not target.exists():shutil.copy2(source,target)
    return str(target)
